-- Managed guest transport. Catalog bindings are reviewed existing resources, not
-- evidence of enrollment or installed software. All bindings begin disabled.
BEGIN;
CREATE TABLE public.sandy_guest_enrollments (
 vm_name text PRIMARY KEY CHECK(vm_name IN ('sandy-windows','sandy-video')),
 instance_id text NOT NULL UNIQUE CHECK(instance_id ~ '^[0-9]{1,22}$'),
 project_id text NOT NULL CHECK(project_id='elaborate-haven-511518-a5'),
 zone text NOT NULL CHECK(zone='europe-west1-b'),
 service_account text NOT NULL CHECK(service_account='sandy-vm-runtime@elaborate-haven-511518-a5.iam.gserviceaccount.com'),
 platform text NOT NULL CHECK(platform IN ('win32','linux')),
 enabled boolean NOT NULL DEFAULT false,generation integer NOT NULL DEFAULT 0 CHECK(generation>=0),
 key_id text,public_key_sha256 text,worker_sha256 text,last_seen_at timestamptz,agent_version text,
 enrolled_by uuid,enrolled_at timestamptz,revoked_at timestamptz,last_boot_id_sha256 text,
 CHECK(public_key_sha256 IS NULL OR public_key_sha256 ~ '^[a-f0-9]{64}$'),
 CHECK(worker_sha256 IS NULL OR worker_sha256 ~ '^[a-f0-9]{64}$')
);
INSERT INTO public.sandy_guest_enrollments(vm_name,instance_id,project_id,zone,service_account,platform) VALUES
 ('sandy-windows','8120150462304566315','elaborate-haven-511518-a5','europe-west1-b','sandy-vm-runtime@elaborate-haven-511518-a5.iam.gserviceaccount.com','win32'),
 ('sandy-video','6831598645020395570','elaborate-haven-511518-a5','europe-west1-b','sandy-vm-runtime@elaborate-haven-511518-a5.iam.gserviceaccount.com','linux');
CREATE TABLE public.sandy_guest_jobs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,admission_id uuid NOT NULL UNIQUE REFERENCES public.sandy_api_execution_admissions(id),
 vm_name text NOT NULL REFERENCES public.sandy_guest_enrollments(vm_name),generation integer NOT NULL,
 operation text NOT NULL,request_id uuid NOT NULL,input_sha256 text NOT NULL,arguments jsonb NOT NULL,
 registry_revision_sha256 text NOT NULL,state text NOT NULL DEFAULT 'queued'
 CHECK(state IN ('queued','claimed','running','completed','accepted','failed','unknown','cancelled','expired','blocked')),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '5 minutes',
 lease_id uuid UNIQUE,nonce uuid,lease_expires_at timestamptz,started_at timestamptz,finished_at timestamptz,
 result_sha256 text,result_digest_format text NOT NULL DEFAULT 'canonical_json_v1' CHECK(result_digest_format IN ('canonical_json_v1','pg_jsonb_v1')),evidence jsonb,UNIQUE(actor_id,request_id),CHECK(octet_length(arguments::text)<=196608)
);
CREATE TABLE public.sandy_guest_access_receipts (
 admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id),actor_id uuid NOT NULL,
 operation text NOT NULL,vm_name text NOT NULL,result jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX sandy_guest_jobs_dispatch ON public.sandy_guest_jobs(vm_name,created_at) WHERE state='queued';
CREATE INDEX sandy_guest_jobs_owner ON public.sandy_guest_jobs(actor_id,created_at DESC);
ALTER TABLE public.sandy_guest_enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_guest_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_guest_access_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sandy_guest_enrollments,public.sandy_guest_jobs,public.sandy_guest_access_receipts FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.sandy_guest_admission_current(p_admission_id uuid,p_actor_id uuid,p_operation text,p_input_sha256 text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions a
 JOIN public.sandy_operation_registry r ON r.operation=a.operation
 LEFT JOIN public.sandy_api_mutation_approval_snapshots proof ON proof.job_id=a.approval_id
 LEFT JOIN public.sandy_deployment_jobs job ON job.id=a.approval_id
 WHERE a.id=p_admission_id AND a.actor_id=p_actor_id AND a.operation=p_operation AND a.input_sha256=p_input_sha256
 AND a.tenant_id IS NULL AND a.credential_id IS NULL AND a.state='consumed'
 AND public.sandy_api_current_owner(p_actor_id) AND r.handler='sandy-guest-operation-api'
 AND r.api_exposed=true AND r.verified=true AND a.registry_revision_sha256=public.sandy_api_registry_revision(a.operation)
 AND (NOT(r.is_mutation OR coalesce(r.error_contract->>'requires_approval'='true',false))
 OR (proof.actor_id=p_actor_id AND job.status='running' AND proof.job_fingerprint_sha256=public.sandy_api_job_fingerprint(job)
 AND EXISTS(SELECT 1 FROM public.sandy_engineering_changes c WHERE c.id=proof.engineering_change_id AND c.status='approved'))))
$$;
CREATE FUNCTION public.sandy_guest_access(p_actor_id uuid,p_vm_name text,p_operation text,p_admission_id uuid,p_input_sha256 text,
 p_key_id text,p_public_key_sha256 text,p_worker_sha256 text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE e public.sandy_guest_enrollments%ROWTYPE; prior jsonb;result jsonb;
BEGIN
 IF NOT public.sandy_api_current_owner(p_actor_id) THEN RETURN jsonb_build_object('ok',false,'error','owner_required','http_status',403); END IF;
 IF encode(extensions.digest('{"vm_name":'||to_jsonb(p_vm_name)::text||'}','sha256'),'hex') IS DISTINCT FROM p_input_sha256 THEN RETURN jsonb_build_object('ok',false,'error','guest_input_digest_mismatch','http_status',400); END IF;
 PERFORM 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission_id FOR UPDATE;
 SELECT r.result INTO prior FROM public.sandy_guest_access_receipts r WHERE admission_id=p_admission_id AND actor_id=p_actor_id AND operation=p_operation AND vm_name=p_vm_name;
 IF FOUND THEN RETURN prior||jsonb_build_object('reused',true); END IF;
 IF p_operation NOT IN ('gcp.vm.access.bootstrap','gcp.vm.access.rotate','gcp.vm.access.revoke') OR NOT public.sandy_guest_admission_current(p_admission_id,p_actor_id,p_operation,p_input_sha256) THEN
 RETURN jsonb_build_object('ok',false,'error','guest_verified_approval_required','http_status',403); END IF;
 IF p_operation<>'gcp.vm.access.revoke' AND (p_key_id IS NULL OR p_key_id !~ '^[A-Za-z0-9_.-]{1,64}$' OR p_public_key_sha256 IS NULL OR p_public_key_sha256 !~ '^[a-f0-9]{64}$'
 OR p_worker_sha256 IS NULL OR p_worker_sha256 !~ '^[a-f0-9]{64}$') THEN RETURN jsonb_build_object('ok',false,'error','guest_signing_configuration_required','http_status',503); END IF;
 SELECT * INTO e FROM public.sandy_guest_enrollments WHERE vm_name=p_vm_name FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','fixed_vm_required','http_status',404); END IF;
 IF p_operation='gcp.vm.access.rotate' AND NOT e.enabled THEN RETURN jsonb_build_object('ok',false,'error','guest_enrollment_required','http_status',409); END IF;
 UPDATE public.sandy_guest_enrollments SET enabled=p_operation<>'gcp.vm.access.revoke',generation=generation+1,
 key_id=CASE WHEN p_operation='gcp.vm.access.revoke' THEN key_id ELSE p_key_id END,
 public_key_sha256=CASE WHEN p_operation='gcp.vm.access.revoke' THEN public_key_sha256 ELSE p_public_key_sha256 END,
 worker_sha256=CASE WHEN p_operation='gcp.vm.access.revoke' THEN worker_sha256 ELSE p_worker_sha256 END,
 enrolled_by=p_actor_id,enrolled_at=clock_timestamp(),revoked_at=CASE WHEN p_operation='gcp.vm.access.revoke' THEN clock_timestamp() ELSE NULL END,
 last_seen_at=NULL,agent_version=NULL WHERE vm_name=p_vm_name RETURNING * INTO e;
 UPDATE public.sandy_guest_jobs SET state=CASE WHEN state='queued' THEN 'cancelled' ELSE 'unknown' END,
 finished_at=clock_timestamp() WHERE vm_name=p_vm_name AND state IN ('queued','claimed','running');
 PERFORM public.sandy_api_append_audit(p_actor_id,p_operation,NULL,NULL,p_admission_id,'guest_access',CASE WHEN e.enabled THEN 'enrolled' ELSE 'revoked' END,p_input_sha256);
 result:=jsonb_build_object('ok',true,'vm_name',e.vm_name,'enabled',e.enabled,'generation',e.generation,
 'instance_id',e.instance_id,'project_id',e.project_id,'key_id',e.key_id,'agent_connected',false,
 'revocation_cancels_already_running_os_effects',false,'reused',false);
 INSERT INTO public.sandy_guest_access_receipts(admission_id,actor_id,operation,vm_name,result) VALUES(p_admission_id,p_actor_id,p_operation,p_vm_name,result);
 RETURN result;
END $$;
CREATE FUNCTION public.sandy_guest_enqueue(p_actor_id uuid,p_vm_name text,p_operation text,p_admission_id uuid,
 p_request_id uuid,p_arguments_canonical text,p_input_sha256 text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE e public.sandy_guest_enrollments%ROWTYPE;j public.sandy_guest_jobs%ROWTYPE;args jsonb;
BEGIN
 IF p_arguments_canonical IS NULL OR octet_length(p_arguments_canonical)>196608 OR
 encode(extensions.digest(p_arguments_canonical,'sha256'),'hex') IS DISTINCT FROM p_input_sha256 THEN RETURN jsonb_build_object('ok',false,'error','guest_input_digest_mismatch','http_status',400); END IF;
 args:=p_arguments_canonical::jsonb;
 IF args->>'vm_name' IS DISTINCT FROM p_vm_name OR jsonb_typeof(args)<>'object' THEN RETURN jsonb_build_object('ok',false,'error','fixed_vm_required','http_status',400); END IF;
 IF p_operation NOT IN ('gcp.vm.files.upload','gcp.vm.files.download','gcp.vm.packages.install','gcp.vm.packages.update','gcp.vm.packages.remove',
 'gcp.vm.services.start','gcp.vm.services.stop','gcp.vm.services.restart','gcp.vm.services.status','gcp.vm.reboot','gcp.vm.firewall_guest.manage')
 OR NOT public.sandy_guest_admission_current(p_admission_id,p_actor_id,p_operation,p_input_sha256)
 OR NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission_id AND request_id=p_request_id) THEN
 RETURN jsonb_build_object('ok',false,'error','guest_verified_approval_required','http_status',403); END IF;
 SELECT * INTO e FROM public.sandy_guest_enrollments WHERE vm_name=p_vm_name FOR SHARE;
 IF NOT FOUND OR NOT e.enabled THEN RETURN jsonb_build_object('ok',false,'error','guest_enrollment_required','http_status',424); END IF;
 INSERT INTO public.sandy_guest_jobs(actor_id,admission_id,vm_name,generation,operation,request_id,input_sha256,arguments,registry_revision_sha256)
 VALUES(p_actor_id,p_admission_id,p_vm_name,e.generation,p_operation,p_request_id,p_input_sha256,args,public.sandy_api_registry_revision(p_operation))
 ON CONFLICT(admission_id) DO NOTHING RETURNING * INTO j;
 IF NOT FOUND THEN SELECT * INTO j FROM public.sandy_guest_jobs WHERE admission_id=p_admission_id;
 RETURN jsonb_build_object('ok',true,'job_id',j.id,'state',j.state,'reused',true,'executed',NULL,'redispatch_permitted',false); END IF;
 PERFORM public.sandy_api_append_audit(p_actor_id,p_operation,p_request_id,NULL,p_admission_id,'guest_queue','queued',p_input_sha256);
 RETURN jsonb_build_object('ok',true,'job_id',j.id,'state',j.state,'reused',false,'executed',false,'expires_at',j.expires_at,'redispatch_permitted',false);
END $$;
CREATE FUNCTION public.sandy_guest_get_status(p_actor_id uuid,p_vm_name text DEFAULT NULL,p_job_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE e public.sandy_guest_enrollments%ROWTYPE;j public.sandy_guest_jobs%ROWTYPE;
BEGIN
 IF NOT public.sandy_api_current_owner(p_actor_id) THEN RETURN jsonb_build_object('ok',false,'error','owner_required','http_status',403); END IF;
 IF p_job_id IS NOT NULL THEN
 SELECT * INTO j FROM public.sandy_guest_jobs WHERE id=p_job_id AND actor_id=p_actor_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','guest_job_not_found','http_status',404); END IF;
 RETURN jsonb_build_object('ok',true,'job_id',j.id,'vm_name',j.vm_name,'operation',j.operation,'request_id',j.request_id,
 'state',CASE WHEN j.state='queued' AND j.expires_at<=clock_timestamp() THEN 'expired'
 WHEN j.state IN ('claimed','running') AND j.lease_expires_at<=clock_timestamp() THEN 'unknown' ELSE j.state END,
 'executed',CASE WHEN j.state IN ('queued','cancelled','expired','blocked') THEN false WHEN j.state IN ('completed','accepted') THEN true ELSE NULL END,
 'result_sha256',j.result_sha256,'result_digest_format',j.result_digest_format,'evidence',j.evidence,'created_at',j.created_at,'finished_at',j.finished_at,
 'reconciliation_required',j.state IN ('claimed','running','accepted','unknown'),'redispatch_permitted',false,
 'evidence_basis','authenticated_fixed_vm_report_not_independent_provider_attestation'); END IF;
 SELECT * INTO e FROM public.sandy_guest_enrollments WHERE vm_name=p_vm_name;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','fixed_vm_required','http_status',404); END IF;
 RETURN jsonb_build_object('ok',true,'vm_name',e.vm_name,'enabled',e.enabled,'generation',e.generation,
 'instance_id',e.instance_id,'project_id',e.project_id,'platform',e.platform,'last_seen_at',e.last_seen_at,
 'agent_version',e.agent_version,'agent_connected',e.enabled AND coalesce(e.last_seen_at>clock_timestamp()-interval '2 minutes',false),
 'installed_software_attested',false,'ssh_transport_available',false,'winrm_transport_available',false);
END $$;
CREATE FUNCTION public.sandy_guest_heartbeat(p_vm_name text,p_instance_id text,p_generation integer,p_key_id text,p_agent_version text,p_platform text,p_boot_id text,p_worker_sha256 text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE current_boot text;j public.sandy_guest_jobs%ROWTYPE;
BEGIN
 IF p_boot_id IS NULL OR p_boot_id !~ '^[A-Za-z0-9:.+-]{1,100}$' THEN RETURN jsonb_build_object('ok',false,'error','guest_boot_identity_invalid','http_status',400); END IF;
 current_boot:=encode(extensions.digest(p_boot_id,'sha256'),'hex');
 UPDATE public.sandy_guest_enrollments SET last_seen_at=clock_timestamp(),agent_version=p_agent_version,last_boot_id_sha256=current_boot
 WHERE vm_name=p_vm_name AND instance_id=p_instance_id AND enabled=true AND generation=p_generation
 AND key_id=p_key_id AND p_agent_version='1.0.0' AND platform=p_platform AND worker_sha256=p_worker_sha256;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','guest_identity_or_enrollment_denied','http_status',403); END IF;
 FOR j IN SELECT * FROM public.sandy_guest_jobs WHERE vm_name=p_vm_name AND generation=p_generation AND operation='gcp.vm.reboot'
 AND state='accepted' AND evidence->>'before_boot_id_sha256' IS NOT NULL AND evidence->>'before_boot_id_sha256'<>current_boot FOR UPDATE LOOP
 UPDATE public.sandy_guest_jobs SET state='completed',finished_at=clock_timestamp(),
 evidence=evidence||jsonb_build_object('reboot_observed',true,'observed_boot_id_sha256',current_boot,'completion_basis','fixed_vm_boot_identity_changed_after_accepted_request'),
 result_sha256=encode(extensions.digest((evidence||jsonb_build_object('reboot_observed',true,'observed_boot_id_sha256',current_boot,'completion_basis','fixed_vm_boot_identity_changed_after_accepted_request'))::text,'sha256'),'hex'),result_digest_format='pg_jsonb_v1' WHERE id=j.id;
 PERFORM public.sandy_api_append_audit(j.actor_id,j.operation,j.request_id,NULL,j.admission_id,'guest_readback','reboot_observed',j.input_sha256,current_boot);
 END LOOP;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.sandy_guest_claim(p_vm_name text,p_instance_id text,p_key_id text,p_public_key_sha256 text,p_worker_sha256 text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE e public.sandy_guest_enrollments%ROWTYPE;j public.sandy_guest_jobs%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('sandy_guest:'||p_vm_name,0));
 SELECT * INTO e FROM public.sandy_guest_enrollments WHERE vm_name=p_vm_name AND instance_id=p_instance_id AND enabled=true AND key_id=p_key_id
 AND public_key_sha256=p_public_key_sha256 AND worker_sha256=p_worker_sha256 FOR SHARE;
 IF NOT FOUND OR e.last_seen_at IS NULL OR e.last_seen_at<clock_timestamp()-interval '2 minutes' THEN RETURN jsonb_build_object('ok',false,'error','guest_identity_or_enrollment_denied','http_status',403); END IF;
 UPDATE public.sandy_guest_jobs SET state='unknown',finished_at=clock_timestamp()
 WHERE vm_name=p_vm_name AND state IN ('claimed','running') AND lease_expires_at<=clock_timestamp();
 UPDATE public.sandy_guest_jobs SET state='expired',finished_at=clock_timestamp() WHERE vm_name=p_vm_name AND state='queued' AND expires_at<=clock_timestamp();
 IF EXISTS(SELECT 1 FROM public.sandy_guest_jobs WHERE vm_name=p_vm_name AND state IN ('claimed','running')) THEN RETURN jsonb_build_object('ok',true,'task',NULL); END IF;
 SELECT * INTO j FROM public.sandy_guest_jobs WHERE vm_name=p_vm_name AND state='queued' AND expires_at>clock_timestamp() ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',true,'task',NULL); END IF;
 IF j.generation<>e.generation OR NOT public.sandy_guest_admission_current(j.admission_id,j.actor_id,j.operation,j.input_sha256)
 OR j.registry_revision_sha256 IS DISTINCT FROM public.sandy_api_registry_revision(j.operation) THEN
 UPDATE public.sandy_guest_jobs SET state='blocked',finished_at=clock_timestamp() WHERE id=j.id;
 RETURN jsonb_build_object('ok',true,'task',NULL); END IF;
 UPDATE public.sandy_guest_jobs SET state='claimed',lease_id=gen_random_uuid(),nonce=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '120 seconds'
 WHERE id=j.id RETURNING * INTO j;
 PERFORM public.sandy_api_append_audit(j.actor_id,j.operation,j.request_id,NULL,j.admission_id,'guest_claim','claimed',j.input_sha256);
 RETURN jsonb_build_object('ok',true,'task',jsonb_build_object('version','1.0.0','key_id',e.key_id,'vm_name',e.vm_name,
 'instance_id',e.instance_id,'project_id',e.project_id,'generation',e.generation,'job_id',j.id,'lease_id',j.lease_id,'nonce',j.nonce,
 'operation',j.operation,'arguments',j.arguments,'input_sha256',j.input_sha256,
 'issued_at',floor(extract(epoch FROM clock_timestamp()))::bigint,'expires_at',floor(extract(epoch FROM j.lease_expires_at))::bigint));
END $$;
CREATE FUNCTION public.sandy_guest_start(p_vm_name text,p_instance_id text,p_job_id uuid,p_lease_id uuid,p_nonce uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE j public.sandy_guest_jobs%ROWTYPE;
BEGIN
 SELECT * INTO j FROM public.sandy_guest_jobs WHERE id=p_job_id FOR UPDATE;
 IF NOT FOUND OR j.vm_name IS DISTINCT FROM p_vm_name OR j.state<>'claimed' OR j.lease_id IS DISTINCT FROM p_lease_id
 OR j.nonce IS DISTINCT FROM p_nonce OR j.lease_expires_at<=clock_timestamp()
 OR NOT EXISTS(SELECT 1 FROM public.sandy_guest_enrollments e WHERE e.vm_name=p_vm_name AND e.instance_id=p_instance_id AND e.enabled=true AND e.generation=j.generation)
 OR NOT public.sandy_guest_admission_current(j.admission_id,j.actor_id,j.operation,j.input_sha256) THEN
 RETURN jsonb_build_object('ok',false,'allowed',false,'error','guest_execution_start_denied','http_status',409); END IF;
 UPDATE public.sandy_guest_jobs SET state='running',started_at=clock_timestamp(),lease_expires_at=clock_timestamp()+interval '5 minutes' WHERE id=j.id;
 PERFORM public.sandy_api_append_audit(j.actor_id,j.operation,j.request_id,NULL,j.admission_id,'guest_start','running',j.input_sha256);
 RETURN jsonb_build_object('ok',true,'allowed',true);
END $$;
CREATE FUNCTION public.sandy_guest_finish(p_vm_name text,p_instance_id text,p_job_id uuid,p_lease_id uuid,p_nonce uuid,
 p_outcome text,p_evidence_canonical text,p_result_sha256 text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE j public.sandy_guest_jobs%ROWTYPE;projection jsonb;
BEGIN
 IF p_outcome IS NULL OR p_outcome NOT IN ('completed','accepted','failed','unknown') OR p_evidence_canonical IS NULL
 OR octet_length(p_evidence_canonical)>100000 OR encode(extensions.digest(p_evidence_canonical,'sha256'),'hex') IS DISTINCT FROM p_result_sha256 THEN
 RETURN jsonb_build_object('ok',false,'error','guest_result_invalid','http_status',400); END IF;
 projection:=p_evidence_canonical::jsonb;
 SELECT * INTO j FROM public.sandy_guest_jobs WHERE id=p_job_id FOR UPDATE;
 IF NOT FOUND OR j.vm_name IS DISTINCT FROM p_vm_name OR j.lease_id IS DISTINCT FROM p_lease_id OR j.nonce IS DISTINCT FROM p_nonce
 OR NOT EXISTS(SELECT 1 FROM public.sandy_guest_enrollments e WHERE e.vm_name=p_vm_name AND e.instance_id=p_instance_id) THEN
 RETURN jsonb_build_object('ok',false,'error','guest_result_scope_denied','http_status',403); END IF;
 IF j.state IN ('completed','accepted','failed','unknown') THEN
 IF j.state=p_outcome AND j.result_sha256=p_result_sha256 THEN RETURN jsonb_build_object('ok',true,'recorded',true,'reused',true); END IF;
 RETURN jsonb_build_object('ok',false,'error','guest_result_conflict','http_status',409); END IF;
 IF j.state<>'running' OR j.lease_expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('ok',false,'error','guest_result_needs_reconciliation','http_status',409); END IF;
 IF j.operation='gcp.vm.reboot' AND p_outcome='completed' THEN RETURN jsonb_build_object('ok',false,'error','guest_reboot_readback_required','http_status',409); END IF;
 IF p_outcome='completed' AND NOT coalesce(CASE
 WHEN j.operation='gcp.vm.files.upload' THEN projection->>'kind'='file_readback' AND projection->>'path'=j.arguments->>'path'
 AND projection->>'sha256'=j.arguments->>'sha256' AND (projection->>'bytes')::bigint BETWEEN 0 AND 65536
 WHEN j.operation='gcp.vm.files.download' THEN projection->>'kind'='file_read' AND projection->>'path'=j.arguments->>'path'
 AND projection->>'sha256'=encode(extensions.digest(decode(projection->>'content_base64','base64'),'sha256'),'hex')
 AND (projection->>'bytes')::bigint=octet_length(decode(projection->>'content_base64','base64')) AND (projection->>'bytes')::bigint BETWEEN 0 AND 65536
 WHEN j.operation LIKE 'gcp.vm.services.%' THEN projection->>'kind'='service_readback' AND projection->>'service'=j.arguments->>'service'
 AND projection->>'mutation_exit_code'='0' AND projection->>'readback_exit_code'='0'
 AND (j.operation='gcp.vm.services.status' OR (j.operation='gcp.vm.services.stop' AND projection->>'state' IN ('inactive','Stopped'))
 OR (j.operation IN ('gcp.vm.services.start','gcp.vm.services.restart') AND projection->>'state' IN ('active','Running')))
 WHEN j.operation LIKE 'gcp.vm.packages.%' THEN projection->>'kind'='package_manager_result' AND projection->>'exit_code'='0' AND projection->>'inventory_confirmed'='true'
 WHEN j.operation='gcp.vm.firewall_guest.manage' THEN projection->>'kind'='firewall_readback' AND projection->>'rule_id'=j.arguments->>'rule_id'
 AND projection->>'mutation_exit_code'='0' AND projection->>'readback_exit_code'='0' AND projection->>'effect_confirmed'='true'
 ELSE false END,false) THEN RETURN jsonb_build_object('ok',false,'error','guest_completion_readback_required','http_status',409); END IF;

 UPDATE public.sandy_guest_jobs SET state=p_outcome,evidence=projection,result_sha256=p_result_sha256,finished_at=clock_timestamp() WHERE id=j.id;
 PERFORM public.sandy_api_append_audit(j.actor_id,j.operation,j.request_id,NULL,j.admission_id,'guest_result',p_outcome,j.input_sha256,p_result_sha256);
 -- Trusted-VM completion evidence is recorded without bypassing the shared
 -- requirement for independent mutation readback: mutations remain accepted.
 PERFORM public.sandy_api_finish_execution(j.admission_id,CASE WHEN p_outcome='completed' THEN
 CASE WHEN (SELECT is_mutation FROM public.sandy_api_execution_admissions WHERE id=j.admission_id) THEN 'accepted' ELSE 'succeeded' END
 WHEN p_outcome='accepted' THEN 'accepted' ELSE p_outcome END,CASE WHEN p_outcome='unknown' THEN NULL ELSE 200 END,NULL,p_result_sha256);
 RETURN jsonb_build_object('ok',true,'recorded',true,'reused',false,'state',p_outcome,
 'evidence_basis','authenticated_fixed_vm_report_not_independent_provider_attestation',
 'reconciliation_required',p_outcome IN ('accepted','unknown'));
END $$;
DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure AS signature,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname IN ('sandy_guest_admission_current','sandy_guest_access','sandy_guest_enqueue',
 'sandy_guest_get_status','sandy_guest_heartbeat','sandy_guest_claim','sandy_guest_start','sandy_guest_finish') LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',f.signature);
 IF f.proname<>'sandy_guest_admission_current' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.signature);END IF;
 END LOOP;
END $$;
